  'describe.rooms.unsettled': 'su texto de estancias no pudo comprobarse frente al plano en {rounds} escrituras',
  'describe.rooms.leftOut': 'Se deja fuera: el muro {wall} no tiene longitud, pues sus dos extremos son un mismo punto, así que la comprobación también lo deja fuera del plano, y escribir este texto da el plano sin él.',
  'describe.rooms.leftOut.opening': 'Se deja fuera: el hueco {opening} está en el muro {wall}, que no tiene longitud, así que la comprobación también lo deja fuera del plano.',
  // WRT-14: la línea de planta del texto de estancias y sus rechazos, cada uno seguido de cómo se escribe.
  'rooms.floor.form': 'floor <id> ["<name>"] [level <n>] [elevation <m>] [height <m>] [slab <m>] [building <kind>] [copy <floor> [with openings]]',
  'rooms.floor.how':
    "Una línea de planta se escribe '{form}', con su nombre entre comillas o sin él, y entonces se llama como su id. level es el número de planta (0 la planta baja, 1 la de encima, -1 un sótano, 0.5 una media planta), nunca una altura. elevation son los metros desde el nivel de la planta baja hasta el de esta planta; height los metros desde esta planta hasta su techo, que toman sus muros; slab el grueso del forjado sobre el que está. Una planta sin elevation se apoya en la de abajo: la elevation y la height de esa planta, más su propio slab. Así, la altura de planta a planta es la height de abajo más el slab de arriba: escriba una altura de planta a planta como la elevation de cada planta, no como su height.",
  'rooms.floor.noId': 'Una línea de planta nombra el id de la planta después de la palabra floor.',
  'rooms.floor.unquoted': "'{word}' no es una palabra que conozca una línea de planta, y el nombre de una planta se escribe entre comillas. Escríbala: '{line}'.",
  'rooms.floor.settingName': "El nombre {name} se lee como el ajuste '{setting}', que se escribe después del nombre sin = ni :. Escríbala: '{line}'.",
  'rooms.floor.unknown': "'{word}' no es una palabra que conozca una línea de planta.",
  'rooms.floor.noValue': "'{word}' necesita su valor detrás: {takes}.",
  'rooms.floor.takes.name': 'name "<nombre>", el nombre de la planta entre comillas',
  'rooms.floor.takes.level': 'level <n>, el número de planta (0 la planta baja, 1 la de encima, -1 un sótano)',
  'rooms.floor.takes.elevation': 'elevation <m>, los metros desde el nivel de la planta baja hasta el de esta planta',
  'rooms.floor.takes.height': 'height <m>, los metros desde esta planta hasta su techo',
  'rooms.floor.takes.slab': "slab <m>, el espesor del forjado sobre el que se apoya, como 'slab 0.25'",
  'rooms.floor.takes.building': 'building <tipo>, uno de: {kinds}',
  'rooms.floor.numberName': "'{word}' está donde va el nombre de la planta, justo después de su id, y el nombre de una planta se escribe entre comillas; cada cifra detrás sigue a su palabra (level, elevation, height o slab).",
  'rooms.floor.numberName.level': "'{word}' está donde va el nombre de la planta, justo después de su id, y el nombre de una planta se escribe entre comillas. Si {word} es el número de planta, va detrás de la palabra level. Escríbala: '{line}'.",
  'rooms.floor.nameLate': "El nombre de la planta {name} se escribe justo después de su id, antes de los ajustes. Escríbala: '{line}'.",
  'rooms.floor.twice': "'{word}' está escrito dos veces en la línea de planta.",
  'rooms.floor.levelLength': "'level {value}' es una longitud, y level es el número de planta. Para la altura de esta planta sobre la planta baja, escriba 'elevation {value}'.",
  'rooms.floor.levelFraction': "'level {value}' no es un número de planta: un level es un número entero, o una mitad (0.5) para una media planta. Para la altura de esta planta sobre la planta baja, escriba 'elevation {value}'.",
  'rooms.floor.building': "'{word}' no es un tipo de edificio que Grid conozca. Use uno de: {kinds}.",
  'rooms.floor.duplicate': "La planta '{id}' ya está escrita.",
  'rooms.floor.roomsFirst': 'Se escribieron estancias antes de la primera línea de planta. Ponga primero la línea de planta.',
  'rooms.pairs.unknown': "'{word}' no se entiende aquí. Palabras conocidas: {known}.",
  'rooms.pairs.noValue': "'{word}' necesita su valor detrás. Palabras conocidas: {known}.",
  'rooms.pairs.floorWord': "'{word}' se escribe en la línea de planta, no aquí: floor <id> {word} {value}. Palabras conocidas aquí: {known}.",
  // WRT-35: una palabra que una línea de estancia no admite, todas las que admite y la más probable.
  'rooms.room.unknown':
    "Línea {line}: '{word}' no se entiende en una línea de estancia.{meant} Tras el uso, escriba un tamaño ('3.0 x 4.4' = este-oeste por norte-sur, caras interiores; añada 'centre' u 'outside' para medir a los ejes de los muros o a sus caras exteriores) o 'polygon x,y x,y ...', y luego dónde va: 'at x,y', '<north|south|east|west> of <room>' con 'align', 'shift', 'until' u 'open' si hacen falta, o 'inside <room> corner <ne|nw|se|sw>' con 'wall <t> [kind]' si hace falta. Después, cualquiera de: 'walls <t> [kind]' fija el grosor de los muros propios de la estancia; 'height <m>' su propia altura libre; 'floor <m>' pone su suelo esos metros por encima del suelo de su planta (con un menos, por debajo), para una estancia elevada o rehundida; 'first-wall <wall id>' empieza su contorno en ese muro; 'through <floor>' la repite en cada planta tras esta hasta esa planta; 'tenure <{tenures}>' y 'type \"<text>\"' dicen para quién es y el tipo de estancia propio del estudio; 'outdoor <{outdoor}>', y luego 'roofed' o 'unroofed', la marca como espacio exterior; 'number \"<text>\"' fija su número de estancia, 'dept <text>' su departamento y 'facts <name>=<value> ...' datos propios de la persona (facts department=Ventas capacity=4).",
  'edit.facts.nothing': 'Indica set, unset o number, o más de uno: los datos que dar, los que quitar o el número de la estancia.',
  'edit.facts.noParts': 'Nombra las partes: parts, por id, o las partes que grid_find elegiría (kind, floor, room, where).',
  'edit.facts.noneMet': 'Ninguna parte del plano está a la vez nombrada y elegida, así que no se fijó ningún dato. grid_find con los mismos kind, floor, room y where muestra lo que eligen.',
  'edit.facts.unknownPart': 'La parte {part} no está en este plano.{meant} grid_find muestra las partes por id.',
  'edit.facts.meant': ' ¿Querías decir {part}?',
  'edit.facts.emptyName': 'Un dato necesita un nombre: uno de set o unset lo tiene en blanco.',
  'edit.facts.emptyValue': 'El dato {fact} no recibe valor. Dale uno, o quítalo con unset.',
  'edit.facts.twice': 'La llamada nombra un mismo dato dos veces, como {first} y {second}. Dalo una vez.',
  'edit.facts.ownField': '{fact} es uno de los campos propios de Grid en {part}, no un dato de la persona: {how}.',
  'edit.facts.how.name': 'grid_rename_room da su nombre a una estancia, y el de una planta está en su línea floor',
  'edit.facts.how.use': 'grid_rename_room da su uso a una estancia',
  'edit.facts.how.number': 'number da su número a una estancia',
  'edit.facts.how.area': 'Grid mide la superficie de una estancia o de una planta; da a la cifra otro nombre, como \'area stated\'',
  'edit.facts.numberNotRoom': 'Un número es de una estancia, y {part} no es una estancia. Nombra una estancia para number.',
