  'edit.facts.numberZone': '{room} es una zona de {of}, y una zona no tiene número propio: da el número a {of}.',
  'edit.facts.numberText': 'El número {problem}.',
  'edit.facts.numberTaken': 'La estancia {room} ya tiene el número {number}. Da otro a esta estancia, o antes otro a {room}.',
  'edit.facts.numberNoneMoves': 'Quitar el número a {room} movería los números que Grid cuenta para otras estancias. Dale otro número en su lugar.',
  'edit.facts.number': 'La estancia {room} es ahora el número {number}, no {was}.',
  'edit.facts.numberCounted': 'La estancia {room} es ahora el número {number}; Grid la contaba como {was}.',
  'edit.facts.numberNone': 'La estancia {room} ya no indica número: Grid la cuenta como {number}.',
  'edit.facts.numbersKept': 'Para que no se mueva el número de ninguna otra estancia, las demás reciben los números que mostraban.',
  'edit.facts.set': '{fact} es ahora {value} en {parts}.',
  'edit.facts.setWas': '{part}: {fact} es ahora {value}, no {was}.',
