  'edit.facts.unchanged': 'Las partes ya están así: no hay nada que cambiar.',
  'edit.facts.refused': 'Los datos de {part} no se guardarían: el conjunto {problem}.',
  'edit.facts.noFloors': 'El archivo del plano no enumera plantas, así que una planta no tiene dónde guardar un dato. Escribe antes su línea floor (grid_describe as=rooms, y luego grid_write_rooms).',
  'edit.set.nothing': 'Pasa set o unset, o ambos: los campos a los que dar un valor y los campos que quitar.',
  'edit.set.unknownPart': 'Ningún muro, estancia, planta, pilar, escalera, rampa, plaza o retícula estructural de este plano tiene el id {part}.{meant} grid_find enumera las partes por id.',
  'edit.set.opening': '{part} es una puerta, una ventana o un hueco: lo cambia grid_change_opening, y su tipo grid_change_type.',
  'edit.set.twoLists': 'El id {part} es un {first} y un {second} en este plano: pasa kind para decir cuál.',
  'edit.set.notKind': 'Ningún {kind} de este plano tiene el id {part}: es un {is}.',
