  'edit.set.meantField': ' ¿Quiso decir {field}?',
  'edit.set.id': 'Una parte conserva su id: otras partes, el programa, las marcas de visto y la historia del plano la nombran por él.',
  'edit.set.own': '{field} de un {kind} tiene su propia herramienta: {how}.',
