  'kind.about.toilet': 'Un inodoro con su cisterna: la espalda contra el muro, el fondo desde el muro hasta el frente de la taza.',
  'kind.about.basin': 'Un lavabo: la espalda contra el muro, el grifo detrás.',
  'kind.about.shower': 'Un plato o una cabina de ducha: su huella es el plato.',
  'kind.about.bath': 'Una bañera: su ancho a lo largo del muro en el que está, el desagüe en su extremo izquierdo.',
  'kind.about.kitchen-run': 'Un frente de muebles bajos con su encimera, el fregadero y la placa en él: su ancho es su largo a lo largo del muro.',
  'kind.about.bed': 'Una cama: su espalda es el cabecero, así que su ancho va de lado a lado del cabecero y su fondo es su largo.',
  'kind.about.table': 'Una mesa: de comedor, de centro, auxiliar o mesilla de noche. Su huella es el tablero.',
  'kind.about.chair': 'Una silla: el respaldo a lo largo de su espalda.',
  'kind.about.sofa': 'Un sofá: el respaldo a lo largo de su espalda y un brazo en cada extremo.',
  'kind.about.storage': 'Un armario, una cómoda o unas estanterías: se abre por delante.',
  'kind.about.armchair': 'Un sillón, un asiento para uno con brazos: el respaldo a lo largo de su espalda y un brazo en cada extremo.',
  'kind.about.stool': 'Un taburete, un asiento sin respaldo: su huella es el asiento.',
  'kind.about.desk': 'Un escritorio para trabajar: su huella es el tablero y su espalda es donde va la pantalla.',
  'kind.about.rug': 'Una alfombra: está en el suelo, así que otros elementos se apoyan en ella y no guarda suelo libre propio.',
  'kind.about.plant': 'Una planta en su maceta: su huella es lo que abarcan sus hojas.',
  // CNT-47: the equipment kinds.
  'kind.about.rack': 'Un rack de servidores o de equipos: su ancho a lo largo de la fila y su fondo de la puerta trasera a la delantera.',
  'kind.about.generator': 'Un grupo electrógeno: su ancho a lo largo y su fondo de lado a lado.',
  'kind.about.pump': 'Una bomba: su huella es la carcasa y la bancada.',
  'kind.about.tank': 'Un depósito apoyado en el suelo: su huella es su envolvente.',
  'kind.about.seat': 'Una butaca fija, como en un cine, un teatro o una sala: su respaldo a lo largo de su espalda. Sus filas se escriben con una línea row.',
  'kind.about.pew': 'Un banco con respaldo: su ancho a lo largo de la fila y el respaldo a lo largo de su espalda.',
  'kind.about.altar': 'Un altar o una mesa: su huella es su tablero.',
  'kind.about.fume-cupboard': 'Una vitrina de gases: su espalda contra el muro y la guillotina en su frente, donde se trabaja.',
  'kind.about.lab-bench': 'Una mesa de laboratorio: su ancho a lo largo y las instalaciones a lo largo de su espalda.',
  'kind.about.safety-shower': 'Una ducha de seguridad: su huella es el suelo donde se pone la persona debajo y su altura la del rociador.',
  'kind.about.kennel': 'Una jaula o un box para animales: se abre por su frente. Una batería de ellas se escribe con una línea row.',
  'kind.about.exam-table': 'Una camilla de exploración: el cabezal en su espalda.',
  'kind.about.clinical-sink': 'Un vertedero o lavabo clínico: su espalda contra el muro y el grifo en su espalda.',
  'kind.about.equipment': 'Cualquier otra cosa que se apoya en el suelo, una caja sencilla del tamaño y la altura que se le dan y llamada por su etiqueta: un SAI, un cuadro eléctrico, una máquina.',
