  // --- Espacio exterior, cubierto o descubierto (CNT-7, C26)
  'areas.measure.outdoor.measures': 'La superficie exterior es el suelo de cada local que el plano marca como espacio exterior, cubierto o descubierto, medido hasta las caras de sus muros y bordes como se mide un local.',
  'areas.measure.outdoor.notTakenOff': 'No está en la superficie útil ni en la construida, interior o exterior, ni lo está un muro que solo limita espacio exterior, como una valla o un antepecho.',
  'areas.measure.outdoor.cannotSay': 'El plano no puede decir qué parte de un espacio exterior cuenta una norma local, como parte de un balcón: Grid no cuenta nada de él salvo que quien lo pide indique esa regla y de dónde viene.',
  'areas.note.outdoor': '{area} m² de espacio exterior se dan aparte: no están en la superficie útil ni en la construida, interior o exterior.',
  'outdoor.kind.garden': 'jardín',
  'outdoor.kind.courtyard': 'patio',
  'outdoor.kind.terrace': 'terraza',
  'outdoor.kind.balcony': 'balcón',
  'outdoor.kind.light-well': 'patio de luces',
  'outdoor.kind.porch': 'porche',
  'outdoor.kind.carport': 'cochera',
  'outdoor.kind.other': 'espacio exterior',
  'outdoor.roofed': 'cubierto',
  'outdoor.open': 'descubierto',
  'areas.room.outdoor': ', {kind}, {roofed}: espacio exterior, aparte',
  'areas.outdoor': 'Espacio exterior, aparte: {area} ({kinds}), {roofed} cubiertos y {open} descubiertos. {rule}',
  'areas.outdoor.kind': '{kind} {area}',
  'areas.measure.partyWall.name': 'Superficie hasta los muros medianeros',
  'areas.measure.partyWall.measures': 'La superficie hasta los muros medianeros es el suelo de los locales de una vivienda con los muros y tabiques entre ellos, medida hasta el eje de cada muro que comparte con otra vivienda, con las zonas comunes o con un vecino, y hasta la cara interior de los muros que dan al exterior, o hasta su cara exterior para la cifra a cara exterior.',
  'areas.measure.partyWall.notTakenOff': 'No se descuenta nada de dentro de la vivienda: sus muros interiores, sus tabiques, sus pilares y su escalera, en cada planta en que está, cuentan todos.',
  'areas.measure.partyWall.cannotSay': 'El plano no puede decir qué locales forman una vivienda salvo por su lista de viviendas, así que el suelo que no es de ningún local y el espacio exterior no están en la cifra de ninguna vivienda, y un muro con un vecino cuenta hasta su eje solo cuando el plano lo marca como medianero.',
  'areas.measure.freeFloor.name': 'Suelo libre',
  'areas.measure.freeFloor.measures': 'El suelo libre es la superficie útil de un local menos el suelo que ocupan sus aparatos fijos: sus huellas, unidas donde se solapan, dentro del local.',
  'areas.measure.freeFloor.notTakenOff': 'Solo se descuentan los aparatos fijos que indica el plano, con las medidas que indica: el mobiliario suelto, que el plano no tiene, y el suelo libre delante de un aparato cuentan como libres.',
  'areas.measure.freeFloor.cannotSay': 'El plano no puede decir qué hay en un local más allá de lo que indica: un local sin aparatos fijos es suelo libre entero, y los aparatos de una zona son también de su local.',
  'areas.measure.conditioned.name': 'Superficie habitable climatizada',
  'areas.measure.conditioned.measures': 'La superficie habitable climatizada es el suelo dentro de la cara exterior de los muros que rodean los locales con calefacción o refrigeración, con los muros entre dos de ellos, y un muro entre uno de ellos y un local que no lo está, o el exterior, contado entero; menos cualquier vacío, que no tiene suelo.',
  'areas.measure.conditioned.notTakenOff': 'No se descuentan los muros interiores, los tabiques, las escaleras ni el suelo que no es de ningún local entre los locales climatizados.',
  'areas.measure.conditioned.cannotSay': 'El plano no puede decir qué locales tienen calefacción o refrigeración salvo que un local lo indique: sin indicarlo, un local está climatizado salvo que sea de aparcamiento, y el espacio exterior nunca lo está, así que un porche cerrado, una entrada cubierta o un trastero sin calefacción dibujado como local cuenta hasta que se marca como no climatizado.',
  'areas.measure.underRoof.name': 'Total bajo cubierta',
  'areas.measure.underRoof.measures': 'El total bajo cubierta es la superficie construida exterior, con cada local cerrado dentro, climatizado o no, también un garaje, más el suelo de cada espacio exterior que cubre una cubierta, como un porche, una cochera o una galería, medido hasta sus propios bordes.',
  'areas.measure.underRoof.notTakenOff': 'No se descuentan los muros exteriores, los muros interiores, los locales no climatizados ni el suelo que no es de ningún local.',
  'areas.measure.underRoof.cannotSay': 'El plano no puede decir cuánto vuela una cubierta más allá de los muros, así que un espacio exterior cubierto cuenta por su propio suelo y un vuelo más allá no; un local indicado como exterior no está en ninguna de las dos cifras.',
  'areas.conditioned.massing': 'es un contorno todavía sin locales, así que no se sabe qué parte de su suelo está climatizada',
  'areas.conditioned.byUse': '{room} (de aparcamiento)',
  'areas.conditioned.stated': '{room} (marcado como no climatizado)',
  'areas.note.unconditioned.one': 'Un local no está climatizado, {rooms}: sus {area} m² están en el total bajo cubierta y no en la superficie habitable climatizada, y el muro entre él y los locales climatizados cuenta entero con ellos.',
  'areas.note.unconditioned.many': '{count} locales no están climatizados, {rooms}: sus {area} m² están en el total bajo cubierta y no en la superficie habitable climatizada, y los muros entre ellos y los locales climatizados cuentan enteros con estos.',
  'areas.room.unconditioned': ', no climatizado: solo en el total bajo cubierta',
  'areas.compare.underAir': '{conditioned} climatizados, {underRoof} bajo cubierta',
